type EventCallback = (payload: any) => void;

export class EventBus {
    private subscribers: Map<string, EventCallback[]>;

    constructor() {
        this.subscribers = new Map();
    }

    publish(event: string, payload: any): void {
        const callbacks = this.subscribers.get(event);
        if (callbacks) {
            callbacks.forEach(callback => {
                // Execute callbacks asynchronously to prevent blocking the publisher
                // and to decouple services further.
                setImmediate(() => callback(payload));
            });
        }
    }

    subscribe(event: string, callback: EventCallback): void {
        if (!this.subscribers.has(event)) {
            this.subscribers.set(event, []);
        }
        this.subscribers.get(event)?.push(callback);
    }
}

import { IncomingMessage, ServerResponse } from 'http';

export type UserId = string;
export type ProjectId = string;
export type TaskId = string;
export type CommentId = string;
export type NotificationId = string;

export interface User {
    id: UserId;
    name: string;
    email: string;
}

export interface CreateUserInput {
    name: string;
    email: string;
}

export interface UpdateUserInput {
    name?: string;
    email?: string;
}

export interface Project {
    id: ProjectId;
    name: string;
    description: string;
    memberIds: UserId[];
}

export interface CreateProjectInput {
    name: string;
    description: string;
}

export interface UpdateProjectInput {
    name?: string;
    description?: string;
}

export enum TaskStatus {
    TODO = 'todo',
    IN_PROGRESS = 'in-progress',
    DONE = 'done',
}

export interface Task {
    id: TaskId;
    title: string;
    description: string;
    status: TaskStatus;
    assigneeId: UserId | null;
    projectId: ProjectId;
}

export interface CreateTaskInput {
    title: string;
    description: string;
    projectId: ProjectId;
}

export interface UpdateTaskInput {
    title?: string;
    description?: string;
}

export interface Comment {
    id: CommentId;
    taskId: TaskId;
    authorId: UserId;
    body: string;
    createdAt: string; // ISO 8601 date string
}

export interface CreateCommentInput {
    taskId: TaskId;
    authorId: UserId;
    body: string;
}

export interface Notification {
    id: NotificationId;
    userId: UserId;
    message: string;
    read: boolean;
    createdAt: string; // ISO 8601 date string
}

// Router types
export type HttpMethod = 'GET' | 'POST' | 'PUT' | 'DELETE';

export interface RouteHandlerResult {
    statusCode: number;
    body?: object | string;
    headers?: { [key: string]: string };
}

export type RouteHandler = (
    req: IncomingMessage,
    res: ServerResponse,
    params: { [key: string]: string },
    query: { [key: string]: string },
    body: any
) => Promise<RouteHandlerResult>;

export interface Route {
    method: HttpMethod;
    path: RegExp; // Regex for path matching
    handler: RouteHandler;
    paramNames: string[]; // To extract named parameters from the path
}

import { User, CreateUserInput, UpdateUserInput, UserId } from '../types';
import * as crypto from 'crypto';

export class UserService {
    private users: Map<UserId, User>;

    constructor() {
        this.users = new Map();
    }

    public async getAllUsers(): Promise<User[]> {
        return Array.from(this.users.values());
    }

    public async getUserById(id: UserId): Promise<User | undefined> {
        return this.users.get(id);
    }

    public async createUser(input: CreateUserInput): Promise<User> {
        const newUser: User = {
            id: crypto.randomUUID(),
            name: input.name,
            email: input.email,
        };
        this.users.set(newUser.id, newUser);
        return newUser;
    }

    public async updateUser(id: UserId, input: UpdateUserInput): Promise<User | undefined> {
        const user = this.users.get(id);
        if (!user) {
            return undefined;
        }

        if (input.name !== undefined) {
            user.name = input.name;
        }
        if (input.email !== undefined) {
            user.email = input.email;
        }

        this.users.set(id, user); // Re-set to ensure map updates if user object was copied
        return user;
    }

    public async deleteUser(id: UserId): Promise<boolean> {
        return this.users.delete(id);
    }
}

import { Project, CreateProjectInput, UpdateProjectInput, ProjectId, UserId } from '../types';
import * as crypto from 'crypto';

export class ProjectService {
    private projects: Map<ProjectId, Project>;

    constructor() {
        this.projects = new Map();
    }

    public async getAllProjects(): Promise<Project[]> {
        return Array.from(this.projects.values());
    }

    public async getProjectById(id: ProjectId): Promise<Project | undefined> {
        return this.projects.get(id);
    }

    public async createProject(input: CreateProjectInput): Promise<Project> {
        const newProject: Project = {
            id: crypto.randomUUID(),
            name: input.name,
            description: input.description,
            memberIds: [],
        };
        this.projects.set(newProject.id, newProject);
        return newProject;
    }

    public async updateProject(id: ProjectId, input: UpdateProjectInput): Promise<Project | undefined> {
        const project = this.projects.get(id);
        if (!project) {
            return undefined;
        }

        if (input.name !== undefined) {
            project.name = input.name;
        }
        if (input.description !== undefined) {
            project.description = input.description;
        }

        this.projects.set(id, project);
        return project;
    }

    public async deleteProject(id: ProjectId): Promise<boolean> {
        return this.projects.delete(id);
    }

    public async addMember(projectId: ProjectId, userId: UserId): Promise<Project | undefined> {
        const project = this.projects.get(projectId);
        if (!project) {
            return undefined;
        }

        if (!project.memberIds.includes(userId)) {
            project.memberIds.push(userId);
        }

        this.projects.set(projectId, project);
        return project;
    }

    public async removeMember(projectId: ProjectId, userId: UserId): Promise<Project | undefined> {
        const project = this.projects.get(projectId);
        if (!project) {
            return undefined;
        }

        const initialLength = project.memberIds.length;
        project.memberIds = project.memberIds.filter(id => id !== userId);

        if (project.memberIds.length < initialLength) {
            this.projects.set(projectId, project);
            return project;
        } else {
            // Member not found, return the existing project without changes
            return project;
        }
    }
}

import {
    Task, CreateTaskInput, UpdateTaskInput, TaskId, UserId, ProjectId, TaskStatus
} from '../types';
import { EventBus } from '../event-bus';
import * as crypto from 'crypto';

export class TaskService {
    private tasks: Map<TaskId, Task>;
    private eventBus: EventBus;

    constructor(eventBus: EventBus) {
        this.tasks = new Map();
        this.eventBus = eventBus;
    }

    public async getTasksByProjectId(projectId: ProjectId): Promise<Task[]> {
        return Array.from(this.tasks.values()).filter(task => task.projectId === projectId);
    }

    public async getTaskById(id: TaskId): Promise<Task | undefined> {
        return this.tasks.get(id);
    }

    public async createTask(input: CreateTaskInput): Promise<Task> {
        const newTask: Task = {
            id: crypto.randomUUID(),
            title: input.title,
            description: input.description,
            status: TaskStatus.TODO, // Default status
            assigneeId: null,
            projectId: input.projectId,
        };
        this.tasks.set(newTask.id, newTask);
        return newTask;
    }

    public async updateTask(id: TaskId, input: UpdateTaskInput): Promise<Task | undefined> {
        const task = this.tasks.get(id);
        if (!task) {
            return undefined;
        }

        if (input.title !== undefined) {
            task.title = input.title;
        }
        if (input.description !== undefined) {
            task.description = input.description;
        }

        this.tasks.set(id, task);
        return task;
    }

    public async deleteTask(id: TaskId): Promise<boolean> {
        return this.tasks.delete(id);
    }

    public async changeTaskStatus(id: TaskId, newStatus: TaskStatus): Promise<Task | 'invalid-transition' | undefined> {
        const task = this.tasks.get(id);
        if (!task) {
            return undefined;
        }

        const oldStatus = task.status;

        // Forward-only status transitions
        if (oldStatus === TaskStatus.TODO && newStatus === TaskStatus.IN_PROGRESS) {
            task.status = newStatus;
        } else if (oldStatus === TaskStatus.IN_PROGRESS && newStatus === TaskStatus.DONE) {
            task.status = newStatus;
        } else if (oldStatus === newStatus) {
            // Allow setting to current status (no change)
        } else {
            return 'invalid-transition';
        }

        this.tasks.set(id, task);
        this.eventBus.publish('task.statusChanged', {
            taskId: task.id,
            taskTitle: task.title,
            assigneeId: task.assigneeId,
            oldStatus: oldStatus,
            newStatus: newStatus,
        });
        return task;
    }

    public async assignTask(id: TaskId, assigneeId: UserId): Promise<Task | undefined> {
        const task = this.tasks.get(id);
        if (!task) {
            return undefined;
        }

        task.assigneeId = assigneeId;

        this.tasks.set(id, task);
        this.eventBus.publish('task.assigned', {
            taskId: task.id,
            taskTitle: task.title,
            assigneeId: task.assigneeId,
        });
        return task;
    }
}

import { Comment, CreateCommentInput, CommentId, TaskId, UserId } from '../types';
import { EventBus } from '../event-bus';
import * as crypto from 'crypto';

export class CommentService {
    private comments: Map<CommentId, Comment>;
    private eventBus: EventBus;

    constructor(eventBus: EventBus) {
        this.comments = new Map();
        this.eventBus = eventBus;
    }

    public async getCommentsByTaskId(taskId: TaskId): Promise<Comment[]> {
        return Array.from(this.comments.values()).filter(comment => comment.taskId === taskId);
    }

    public async getCommentById(id: CommentId): Promise<Comment | undefined> {
        return this.comments.get(id);
    }

    public async createComment(input: CreateCommentInput, taskTitle: string, authorName: string): Promise<Comment> {
        const newComment: Comment = {
            id: crypto.randomUUID(),
            taskId: input.taskId,
            authorId: input.authorId,
            body: input.body,
            createdAt: new Date().toISOString(),
        };
        this.comments.set(newComment.id, newComment);
        this.eventBus.publish('comment.added', {
            commentId: newComment.id,
            taskId: newComment.taskId,
            taskTitle: taskTitle,
            authorId: newComment.authorId,
            authorName: authorName,
        });
        return newComment;
    }

    public async deleteComment(id: CommentId): Promise<boolean> {
        return this.comments.delete(id);
    }
}
